<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acessar painel</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@700&display=swap" rel="stylesheet"><link href="<?= base_url('assets/css/styles.css') ?>" rel="stylesheet"><style>body{margin:0;background:#f4f6f5;font-family:"DM Sans",sans-serif;color:#1b2722}.login-shell{min-height:100vh;display:grid;grid-template-columns:1fr 1fr}.login-brand{background:#17211d;color:#fff;padding:64px;display:flex;flex-direction:column;justify-content:space-between;position:relative;overflow:hidden}.login-brand:after{content:"";position:absolute;width:460px;height:460px;border-radius:50%;background:rgba(23,107,77,.35);right:-180px;bottom:-190px}.login-brand__logo{font-family:"Playfair Display",serif;font-size:1.75rem}.login-brand__copy{max-width:520px;position:relative;z-index:1}.login-brand__copy span{color:#d67a5d;font-size:.75rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.login-brand h1{font-family:"Playfair Display",serif;font-size:3.5rem;line-height:1.06;margin:18px 0}.login-brand p{color:rgba(255,255,255,.6);line-height:1.7}.login-panel{display:grid;place-items:center;padding:40px}.login-card{width:min(440px,100%)}.login-card h2{font-size:1.85rem;margin:0 0 7px}.login-card>p{color:#718078;margin-bottom:30px}.login-card label{font-size:.84rem;font-weight:700;margin-bottom:7px}.login-card .form-control{border:1px solid #d9e2dd;border-radius:10px;padding:13px 14px}.login-card .form-control:focus{border-color:#176b4d;box-shadow:0 0 0 3px rgba(23,107,77,.12)}.login-submit{width:100%;border:0;border-radius:10px;background:#176b4d;color:#fff;padding:13px;font-weight:700}.login-back{display:block;text-align:center;margin-top:20px;color:#718078;text-decoration:none;font-size:.86rem}@media(max-width:800px){.login-shell{grid-template-columns:1fr}.login-brand{display:none}.login-panel{padding:26px}}</style></head><body><?= $this->renderSection('conteudo') ?></body></html>
